//! Codegen реестра харнесса `(формат × вид)` из файловой раскладки (ARCHITECTURE.md §5;
//! ORCHESTRATION). Идентичен по смыслу `core/build.rs` (см. там «почему codegen, а не
//! inventory»): DCE в графе `rlib`-ов молча вырезает registry-only модули видов, поэтому
//! реестр строится как ОБЫЧНЫЙ ссылаемый `&[FormatKind]`, ИМЕНУЮЩИЙ символ каждого вида.
//!
//! # Контракт grind-агента
//! Файл `src/metadata/<вид>.rs` ОБЯЗАН определить
//! `pub const HARNESS_ENTRY: formats_xml::FormatKind` (read/write/corpus/layout этого
//! вида). Добавил файл → пересборка подхватывает его в `pub mod` (через `metadata/mod.rs`)
//! и в `FORMAT_KINDS` — без правки общих файлов.

use std::path::Path;

fn main() {
    let dir = Path::new("src/metadata");
    println!("cargo:rerun-if-changed={}", dir.display());

    let mut modules: Vec<String> = Vec::new();
    for entry in std::fs::read_dir(dir).expect("read src/metadata") {
        let path = entry.expect("dir entry").path();
        println!("cargo:rerun-if-changed={}", path.display());
        if path.extension().and_then(|e| e.to_str()) != Some("rs") {
            continue;
        }
        let stem = path
            .file_stem()
            .and_then(|s| s.to_str())
            .expect("utf-8 stem");
        if stem == "mod" {
            continue;
        }
        modules.push(stem.to_string());
    }
    modules.sort();

    let out_dir = std::env::var("OUT_DIR").expect("OUT_DIR");
    let manifest = std::env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR");
    let abs_str = format!("{manifest}/src/metadata").replace('\\', "/");

    // (1) `#[path] pub mod <вид>;` — в `metadata/mod.rs` (модули живут там).
    let mut mods = String::from("// @generated by build.rs — do not edit.\n");
    for m in &modules {
        mods.push_str(&format!("#[path = \"{abs_str}/{m}.rs\"]\npub mod {m};\n"));
    }
    std::fs::write(Path::new(&out_dir).join("metadata_mods.rs"), mods).expect("write mods");

    // (2) `FORMAT_KINDS` — ссылаемый массив строк харнесса; ИМЕНУЕТ `<вид>::HARNESS_ENTRY`,
    //     чем держит модули живыми (DCE-safe). Включается в `metadata/mod.rs`.
    let mut kinds = String::from("// @generated by build.rs — do not edit.\n");
    kinds.push_str(
        "/// Строки харнесса всех видов этого формата (по файлам `src/metadata`).\n\
         /// Ссылаемый `const` держит модули живыми (DCE-safe); testkit сливает реестры\n\
         /// форматов для R+X-харнесса.\n\
         pub static FORMAT_KINDS: &[formats_xml::FormatKind] = &[\n",
    );
    for m in &modules {
        kinds.push_str(&format!("    {m}::HARNESS_ENTRY,\n"));
    }
    kinds.push_str("];\n");
    std::fs::write(Path::new(&out_dir).join("metadata_kinds.rs"), kinds).expect("write kinds");
}
